using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Drawing;
using System.Text.RegularExpressions;
namespace Overclock {
 sealed class HealthView:UserControl {
  readonly IdentityBanner banner=new IdentityBanner{Caption="Drive Health",Model="Select a physical drive",Summary="S.M.A.R.T. assessment, endurance and reported errors",Height=145};readonly Collector disks;readonly DarkCombo select=new DarkCombo{DropDownStyle=ComboBoxStyle.DropDownList,Width=560,DropDownWidth=1050};readonly DataGridView table=Theme.Grid("Drive attribute","Reported value");readonly TextBox raw=new DarkTextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Bottom,Height=180,Visible=false,BackColor=Theme.Surface,ForeColor=Theme.Muted,BorderStyle=BorderStyle.None,Font=new Font("Consolas",9)};readonly MetricCard temperature=new MetricCard(),health=new MetricCard(),life=new MetricCard(),errors=new MetricCard();readonly Label note=Theme.Label("Select a drive to read its health information.",9);readonly Timer timer=new Timer{Interval=1000};DateTime next;bool busy;string diskData="";
  public HealthView(Collector source){Dock=DockStyle.Fill;disks=source;var summary=new TableLayoutPanel{Dock=DockStyle.Top,Height=246,ColumnCount=4,RowCount=1};foreach(var c in new[]{temperature,health,life,errors}){summary.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));c.Dock=DockStyle.Fill;c.Margin=new Padding(0,0,12,12);summary.Controls.Add(c);}temperature.Accent=Theme.AccentSoft;life.Accent=Theme.Secondary;errors.Accent=Theme.Warning;ResetSummary();var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Padding=new Padding(0,0,0,14)};Theme.Combo(select);bar.Controls.Add(select);var refresh=Theme.Button("Refresh",true);bar.Controls.Add(refresh);refresh.Click+=(s,e)=>RefreshHealth();var technical=Theme.Button("Technical details");technical.Click+=(s,e)=>raw.Visible=!raw.Visible;bar.Controls.Add(technical);select.SelectedIndexChanged+=(s,e)=>{banner.Model=DiskScoreData.DriveLabel(select.Text);banner.Invalidate();next=DateTime.MinValue;ResetSummary();note.Text="Reading selected drive…";RefreshHealth();};note.Dock=DockStyle.Top;note.Height=34;var sections=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};sections.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,28));sections.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,72));sections.RowStyles.Add(new RowStyle(SizeType.Percent,100));var warnings=new SectionPanel("Warnings"){Dock=DockStyle.Fill,Margin=new Padding(0,0,12,0)};var guidance=Theme.Label("S.M.A.R.T. health and error counters are independent. Review nonzero counters and the technical report. Missing attributes remain unavailable.",12);guidance.Dock=DockStyle.Fill;warnings.Controls.Add(guidance);var technicalPanel=new SectionPanel("Technical details"){Dock=DockStyle.Fill,Margin=Padding.Empty};technicalPanel.Controls.Add(table);sections.Controls.Add(warnings);sections.Controls.Add(technicalPanel);Controls.Add(sections);Controls.Add(raw);Controls.Add(note);Controls.Add(summary);Controls.Add(bar);Controls.Add(banner);timer.Tick+=(s,e)=>{disks.Request(false);if(disks.Value!=diskData){diskData=disks.Value;string old=select.Text;select.Items.Clear();select.Items.AddRange(diskData.Split('\n').Where(l=>l.StartsWith("Disk #")).Select(l=>l.Trim()).Cast<object>().ToArray());if(select.Items.Contains(old))select.SelectedItem=old;else if(select.Items.Count>0){int preferred=Enumerable.Range(0,select.Items.Count).FirstOrDefault(i=>select.Items[i].ToString().Contains("NVMe"));select.SelectedIndex=preferred;}}if(DateTime.UtcNow>=next)RefreshHealth();};timer.Start();disks.Request(true);Disposed+=(s,e)=>timer.Dispose();}
  void ResetSummary(){temperature.Set("Temperature","—","°C","Drive temperature","Waiting for telemetry","",-1,"—",new float[0]);health.Set("Health","—","reported status","SMART assessment","Waiting for telemetry","",-1,"—",new float[0]);life.Set("Remaining life","—","life remaining","SSD endurance","Not available on every drive","",-1,"—",new float[0]);errors.Set("Media errors","—","reported count","Data integrity","Read the full report for context","",-1,"—",new float[0]);table.Rows.Clear();}
  string Field(string report,string name){var m=Regex.Match(report,@"(?m)^"+name+@":\s*(.+)$");return m.Success?m.Groups[1].Value.Trim():"—";}
  void ShowReport(string report){banner.ArtKey=report.Contains("NVMe Version")||Regex.IsMatch(report,@"Rotation Rate:\s*Solid State",RegexOptions.IgnoreCase)?"storage":null;banner.Invalidate();raw.Text=report;string t=Field(report,"Temperature"),used=Field(report,"Percentage Used"),err=Field(report,"Media and Data Integrity Errors"),assessment=Field(report,"SMART overall-health self-assessment test result");float temp=-1;if(!float.TryParse(Regex.Match(t,@"[0-9]+").Value,out temp))t="—";int percent;bool known=int.TryParse(Regex.Match(used,@"[0-9]+").Value,out percent);string remaining=known?Math.Max(0,100-percent).ToString()+"%":"—";long count;bool errorKnown=long.TryParse(err.Replace(",",""),out count);bool warning=(errorKnown&&count>0)||assessment!="PASSED"&&assessment!="—";temperature.Set("Temperature",t=="—"?"—":temp.ToString("0"),"°C","Composite temperature","Measured by the drive","",t=="—"?-1:temp,t=="—"?"N/A":temp.ToString("0")+"°",new float[0]);health.Set("Health",warning?"Check":assessment=="PASSED"?"OK":"—","SMART assessment",assessment=="—"?"See vendor attributes":assessment,warning?"Error counters need review":"Health and errors are separate","",-1,warning?"!":"✓",new float[0]);life.Set("Remaining life",remaining,"life remaining","NVMe endurance",known?"Derived from Percentage Used":"Vendor attribute may be below","",known?Math.Max(0,100-percent):-1,remaining,new float[0]);errors.Set("Media errors",err,"reported count","Data integrity",errorKnown&&count>0?"Nonzero counter — review details":"Reported by the controller","",-1,errorKnown&&count>0?"!":"—",new float[0]);note.Text=warning?"Attention: the drive reports errors or a warning. Review the counters and technical report.":"Auto refresh every 2 minutes · Missing attributes are shown as unavailable.";note.ForeColor=warning?Theme.Warning:Theme.Muted;table.Rows.Clear();foreach(string key in new[]{"Model Number","Device Model","Serial Number","Firmware Version","NVMe Version","SATA Version is","Critical Warning","Power Cycles","Power On Hours","Data Units Read","Data Units Written","Unsafe Shutdowns","Media and Data Integrity Errors","Error Information Log Entries","smartctl exit bitmask"}){string value=Field(report,key);if(value!="—")table.Rows.Add(key,value);}table.ClearSelection();}
  async void RefreshHealth(){if(busy||select.SelectedItem==null)return;busy=true;next=DateTime.UtcNow.AddSeconds(120);int number=int.Parse(select.Text.Split('|')[0].Replace("Disk #","").Trim());string identity=select.Text;try{string result=await Task.Run(()=>{string path=Path.Combine(Path.GetTempPath(),"overclock-health-"+Guid.NewGuid().ToString("N"));try{using(var p=Workers.StartSelf("health-disk",path,number.ToString())){if(!p.WaitForExit(25000)){Workers.KillTree(p);throw new TimeoutException("SMART provider timed out");}return File.ReadAllText(path);}}finally{try{File.Delete(path);}catch{}}});if(!IsDisposed&&select.Text==identity)ShowReport(result);}catch(Exception e){if(!IsDisposed&&select.Text==identity){note.Text=e.Message;raw.Text=e.ToString();}}finally{busy=false;}}
 }
}



